contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test entry: deposit amount into c from this contract
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // read before-values
        uint256 beforeRecorded = c.balances(address(this));
        uint256 beforeContractBal = address(c).balance;

        // perform deposit, capture whether it reverted
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 afterRecorded = c.balances(address(this));
        uint256 afterContractBal = address(c).balance;

        // Assert general rule:
        // If deposit succeeded: recorded balance increased by at least amount and contract balance increased by exactly amount.
        // If deposit reverted: neither recorded nor contract balance changed.
        assert(
            (!reverted && afterContractBal == beforeContractBal + amount && afterRecorded >= beforeRecorded + amount)
            || (reverted && afterContractBal == beforeContractBal && afterRecorded == beforeRecorded)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test entry: attempt to deposit `amount` wei into c from this contract
    function run(uint256 amount) public payable {
        // ensure this test contract has enough Ether to send
        require(address(this).balance >= amount);

        // record contract balance before the call
        uint256 beforeContractBal = address(c).balance;

        // perform deposit, capture whether it reverted
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // record contract balance after the call
        uint256 afterContractBal = address(c).balance;

        // Assert: either the call reverted and contract balance is unchanged,
        // or it succeeded and contract balance increased by exactly `amount`.
        assert(
            (reverted && afterContractBal == beforeContractBal)
            || (!reverted && afterContractBal == beforeContractBal + amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Test withdraw behavior: caller must have a balance, so first deposit some amount, then try withdraw.
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // ensure this test contract has enough Ether to send for the deposit
        require(address(this).balance >= depositAmount);

        // perform deposit (may revert); we need to ensure deposit succeeded before attempting withdraw,
        // so record whether it reverted.
        bool depReverted;
        try c.deposit{value: depositAmount}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        // Observe balances after deposit attempt
        uint256 contractBalAfterDeposit = address(c).balance;

        // Now attempt withdraw; capture whether it reverted
        bool wdReverted;
        try c.withdraw(withdrawAmount) {
            wdReverted = false;
        } catch {
            wdReverted = true;
        }

        uint256 contractBalAfterWithdraw = address(c).balance;

        // We can observe the reporter's recorded balance via the public getter balances(address)
        // The contract C has mapping balances but it's not declared public in P; however the template
        // forbids accessing non-public. Since balances is not public, we cannot call c.balances(...).
        // Instead, we can reason about observable overall Ether held by c and the effects of withdraw.
        // The general property we assert: if withdraw succeeded then contract balance decreased by exactly withdrawAmount
        // and deposit must not have reverted (since withdraw requires sufficient recorded balance). If withdraw reverted,
        // then either deposit had reverted or the contract balance is unchanged by the withdraw attempt.

        // Assert the general rule stated above.
        assert(
            // Case A: withdraw succeeded
            (!wdReverted && !depReverted && contractBalAfterWithdraw + withdrawAmount == contractBalAfterDeposit)
            ||
            // Case B: withdraw reverted -> contract balance unchanged by the withdraw call
            (wdReverted && contractBalAfterWithdraw == contractBalAfterDeposit)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: amount to seed into c, and target address to migrate to
    function run(uint256 seedAmount, address payable to) public payable {
        // ensure this test contract has enough Ether to seed the contract
        require(address(this).balance >= seedAmount);

        // First, seed the contract with Ether by calling deposit from this contract.
        // deposit may revert if it overflows its internal accounting; capture revert flag.
        bool depositReverted;
        try c.deposit{value: seedAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        // Snapshot contract balance before migrate attempt
        uint256 balBefore = address(c).balance;

        // Attempt migrateTo and capture whether it reverted. Only the creator (the deployer of c)
        // may call migrateTo successfully. In this test, msg.sender is this InvMutTest contract,
        // which ALSO deployed c (per problem statement), so this contract is the creator and
        // migrateTo should succeed when called; if any precondition fails it should revert.
        bool migReverted;
        try c.migrateTo(to) {
            migReverted = false;
        } catch {
            migReverted = true;
        }

        // Snapshot contract balance after migrate attempt
        uint256 balAfter = address(c).balance;

        // The general invariant to assert:
        // - If migrateTo succeeded (did not revert) then balAfter == 0 and balBefore equals the amount transferred out.
        // - If migrateTo reverted then balance is unchanged by the call (balAfter == balBefore).
        // Additionally, if deposit earlier reverted then balBefore should reflect that (i.e., be 0 or unchanged),
        // but we don't require a specific numeric value for balBefore beyond relating it to balAfter.
        assert(
            (!migReverted && balAfter == 0)
            ||
            (migReverted && balAfter == balBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will not call deposit (it may assert), instead rely on any existing balance for this caller.
    // The function takes no Ether; it simply attempts refund and observes effects.
    function run() public payable {
        // read recorded balance for this contract's address before calling refund
        uint256 balRecordedBefore = c.balances(address(this));
        uint256 balContractBefore = address(c).balance;
        uint256 balThisBefore = address(this).balance;

        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        uint256 balRecordedAfter = c.balances(address(this));
        uint256 balContractAfter = address(c).balance;
        uint256 balThisAfter = address(this).balance;

        // If refund reverted, nothing observable should have changed.
        // If refund succeeded, the recorded balance for this caller must be zero,
        // and the contract balance must have decreased by exactly balRecordedBefore,
        // and this contract's balance must have increased by that same amount.
        assert(
            (refundedReverted
                && balRecordedAfter == balRecordedBefore
                && balContractAfter == balContractBefore
                && balThisAfter == balThisBefore)
            ||
            (!refundedReverted
                && balRecordedAfter == 0
                && balContractBefore >= balRecordedBefore
                && balContractAfter + balRecordedBefore == balContractBefore
                && balThisAfter == balThisBefore + balRecordedBefore)
        );
    }

    // accept Ether sent from c during refund
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We drive deposit first to ensure there is something to withdraw from c for this caller (InvMutTest)
    // Then attempt withdraw and check the observable relationship between address(c).balance and address(this).balance
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // deposit into c from this contract
        c.deposit{value: depositAmount}();

        // record balances before withdraw attempt
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule: if withdraw succeeded (did not revert), then C's balance decreased by exactly withdrawAmount
        // and this contract's balance increased by exactly withdrawAmount. If it reverted, balances unchanged.
        assert(
            (reverted && afterC == beforeC && afterThis == beforeThis)
            || (!reverted && beforeC >= withdrawAmount && afterC + withdrawAmount == beforeC && afterThis == beforeThis + withdrawAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call sequence: deposit some Ether as this contract, then call refund and check observable effects.
    // We take depositAmount as input to send to c.deposit, and use no other calls that can assert inside C.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // Deposit into c so that caller (this contract) has a nonzero balance in c.
        c.deposit{value: depositAmount}();

        // Observe balances before refund
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule: If refund did not revert, then C's balance decreased by exactly depositAmount
        // and this contract's balance increased by exactly depositAmount. If it reverted, balances unchanged.
        // Note: rely only on observable balances and revert flag; avoid underflow in expressions by comparing sums.
        assert(
            (refundedReverted && afterC == beforeC && afterThis == beforeThis)
            || (!refundedReverted && afterC + depositAmount == beforeC && afterThis == beforeThis + depositAmount)
