contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = msg.sender; }

    // Parameters: callerIsCreator selects whether this test tries to call migrateTo as creator or as non-creator;
    // to send Ether into c before migration we take fundAmount and require this contract has that balance.
    function run(bool callerIsCreator, address to, uint256 fundAmount) public payable {
        // ensure this test contract has funds available to send to c
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // Fund c so migrateTo has something to transfer if allowed
        if (fundAmount > 0) {
            c.deposit{value: fundAmount}();
        }

        // record balance before attempting migrate
        uint256 beforeC = address(c).balance;

        bool migratedReverted;
        // We must call migrateTo either from this contract (non-creator) or mimic creator by using the deployer address.
        // However the checker deploys C with InvMutTest as msg.sender, so the creator of C is this InvMutTest contract.
        // Thus: if callerIsCreator == true, call migrateTo from this contract (which is creator); otherwise simulate a non-creator call
        // by attempting the call from an external address: we achieve that by calling c.migrateTo within a low-level call that sets
        // msg.sender to this contract still; low-level call cannot change msg.sender. Therefore to model a non-creator call,
        // we instead check the expectation by reasoning about revert: calling migrateTo from this contract should succeed when
        // callerIsCreator==true and revert when false. To simulate a non-creator call we do a try/catch on migrateTo while first
        // transferring the contract's creator role cannot be changed, so a direct call when callerIsCreator is false should revert.

        // Perform the call from this contract in both cases; whether it reverts tells us if this contract is creator.
        try c.migrateTo(to) {
            migratedReverted = false;
        } catch {
            migratedReverted = true;
        }

        uint256 afterC = address(c).balance;

        // General rule: if the call reverted, c's balance must be unchanged; if the call did not revert, c's balance must be zero
        // (since migrateTo transfers the full contract balance to `to`).
        // Note: we express "zero" as afterC == 0 and avoid arithmetic that could under/overflow.
        assert(
            (migratedReverted && afterC == beforeC)
            || (!migratedReverted && afterC == 0)
        );
    }

    // Allow contract to receive Ether for funding the test
    receive() external payable {}
}

