contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take two amounts: depAmount to deposit into c, and wdAmount to attempt to withdraw.
    // The test will deposit depAmount (sent as value) from this contract into c, then try to withdraw wdAmount.
    // We assert that if the withdraw call does not revert then address(c).balance decreased by wdAmount
    // and address(this).balance increased by wdAmount; if it reverts then address(c).balance remains depAmount.
    function run(uint256 depAmount, uint256 wdAmount) public payable {
        require(address(this).balance >= depAmount, "insufficient funds to send deposit");
        // initial contract balance observed
        uint256 beforeC = address(c).balance;
        // perform deposit: send Ether to c.deposit
        c.deposit{value: depAmount}();
        uint256 afterDepositC = address(c).balance;

        // after deposit the contract balance must have increased by depAmount
        // (this is a checkable implication used later in the single assert)
        bool deposit_reflected = (afterDepositC == beforeC + depAmount);

        // now attempt withdraw of wdAmount
        bool withdrew;
        uint256 beforeThis = address(this).balance;
        try c.withdraw(wdAmount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule asserted below:
        // If withdraw succeeded then contract balance decreased by exactly wdAmount and this contract's balance increased by exactly wdAmount
        // If withdraw reverted then contract balance stayed the same as afterDepositC
        assert(
            (withdrew && deposit_reflected && afterC + wdAmount == afterDepositC && afterThis == beforeThis + wdAmount)
            || (!withdrew && afterC == afterDepositC)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit some ether into c from this contract, then call c.refund().
    // Parameters:
    //  depAmount: amount this test contract sends into c via deposit()
    // NOTE: we must have enough balance in this contract to send depAmount.
    function run(uint256 depAmount) public payable {
        require(address(this).balance >= depAmount, "insufficient test balance");

        // Observe c balance before deposit
        uint256 beforeC = address(c).balance;

        // Deposit depAmount into c on behalf of this contract
        c.deposit{value: depAmount}();

        // Observe c balance after deposit
        uint256 afterDepositC = address(c).balance;

        // Now attempt refund(). Capture whether it reverts.
        bool refunded;
        uint256 beforeThis = address(this).balance;
        try c.refund() {
            refunded = true;
        } catch {
            refunded = false;
        }
        uint256 afterThis = address(this).balance;
        uint256 afterC = address(c).balance;

        // General invariant to assert:
        // If refund succeeded then the contract's balance decreased by exactly the amount the test contract received (afterThis - beforeThis),
        // and that amount is <= the deposit we previously made (i.e. <= the caller's prior contribution as far as observable behavior allows).
        // If refund reverted then contract balance remains unchanged from afterDepositC.
        assert(
            (refunded && afterC + (afterThis - beforeThis) == afterDepositC && (afterThis - beforeThis) <= depAmount)
            || (!refunded && afterC == afterDepositC)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address payable target;

    constructor(C _c) {
        c = _c;
        target = payable(address(0xBEEF));
    }

    // We attempt migrateTo(to) and assert a general rule about who can succeed and the effect on c's balance.
    // Param: amount - optional ether to first send into c via deposit() so that migrateTo has some balance to transfer.
    function run(uint256 amount) public payable {
        // ensure this test contract has balance to send 'amount'
        require(address(this).balance >= amount, "insufficient balance for setup");

        // Fund c by calling deposit with 'amount' (this will act as msg.sender = this contract)
        if (amount > 0) {
            c.deposit{value: amount}();
        }

        // Record c balance before migrate attempt
        uint256 before = address(c).balance;

        // Try to call migrateTo; capture whether it reverted
        bool success;
        try c.migrateTo(target) {
            success = true;
        } catch {
            success = false;
        }

        uint256 after = address(c).balance;

        // General rule to assert:
        // If migrateTo succeeded, then c's balance must be zero afterwards (all funds moved out).
        // If migrateTo reverted, then c's balance must be unchanged.
        // This implies only the creator (not this contract) can cause a revert/success pattern inconsistent with moving all funds out.
        assert((success && after == 0) || (!success && after == before));
    }

    receive() external payable {}
}

