contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function with inputs to exercise deposit/withdraw/refund/migrate
    function run(address payable other, uint256 dep1, uint256 dep2, uint256 wdraw, bool useRefund, bool useMigrate) public payable {
        // ensure this contract has funds to forward when calling c.deposit
        // require enough Ether for deposits
        require(address(this).balance >= dep1 + dep2);

        // Start: deposit dep1 from this contract into c
        c.deposit{value: dep1}();

        // Second deposit from this contract (same caller) to aggregate balance
        c.deposit{value: dep2}();

        // record balances before attempting withdrawal/refund/migrate
        uint256 cBalBefore = address(c).balance;
        // note: cannot read internal balances mapping directly; but we can attempt actions and observe effects

        bool withdrewReverted;
        // attempt withdraw by this contract (InvMutTest is msg.sender for calls)
        try c.withdraw(wdraw) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // record after possible withdraw
        uint256 cBalAfterWithdraw = address(c).balance;

        bool refundedReverted;
        if (useRefund) {
            try c.refund() {
                refundedReverted = false;
            } catch {
                refundedReverted = true;
            }
        } else {
            refundedReverted = true; // not called
        }

        uint256 cBalAfterRefund = address(c).balance;

        bool migratedReverted;
        if (useMigrate) {
            // migrate only allowed if InvMutTest is creator; deployment assumption: checker deploys fresh c and passed it in; InvMutTest was used to deploy c per prompt.
            // Try migrating to `other` address
            try c.migrateTo(other) {
                migratedReverted = false;
            } catch {
                migratedReverted = true;
            }
        } else {
            migratedReverted = true;
        }

        uint256 cBalFinal = address(c).balance;

        // General invariant to assert:
        // 1) Any successful withdraw reduced contract balance by at most wdraw and by at least 1 wei when wdraw>0 (but safe to assert non-increase up to wdraw).
        // 2) After a successful refund call, contract balance is reduced by exactly the amount that was stored for this caller at that time. We cannot read stored amount directly, but we can assert that if refund succeeded then c's balance decreased compared to before refund and the caller's subsequent withdraw must revert (since refund zeroes the mapping). To keep the assert expressible only with public surface, we assert consistency: cBalAfterRefund <= cBalAfterWithdraw and if refund succeeded then any subsequent withdraw of full prior balance must revert.

        // Try to withdraw the sum of deposits we made (dep1+dep2) after operations to check refund cleared balance when refund succeeded.
        bool withdrawAfterRefundReverted;
        uint256 tryAmount = dep1 + dep2;
        try c.withdraw(tryAmount) {
            withdrawAfterRefundReverted = false;
        } catch {
            withdrawAfterRefundReverted = true;
        }

        // The final assert composes observable relations:
        // - Contract balance never increases as a result of withdraw/refund/migrate attempts in this sequence
        // - If withdraw succeeded earlier, contract balance decreased by <= wdraw
        // - If refund was called and succeeded, then a subsequent withdraw of the entire prior deposited sum must revert (since refund zeroes caller balance)

        assert(
            // non-increase overall
            cBalFinal <= cBalBefore
            // if withdraw succeeded earlier, the balance drop was at most wdraw
            && (withdrewReverted || cBalBefore - cBalAfterWithdraw <= wdraw)
            // if refund was called and succeeded, then withdrawing full deposited amount afterwards must revert
            && ( (!useRefund || refundedReverted) || withdrawAfterRefundReverted )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint256 dep1, uint256 dep2, uint256 tryWithdraw, address payable other) public payable {
        // ensure this contract has funds to forward when calling c.deposit
        require(address(this).balance >= dep1 + dep2);

        // Make two deposits from this tester (msg.sender for c is this contract)
        c.deposit{value: dep1}();
        c.deposit{value: dep2}();

        // record contract balance before any withdrawals/refunds
        uint256 cBalBefore = address(c).balance;

        // attempt an initial withdraw of tryWithdraw and record if it reverted
        bool withdrewReverted;
        try c.withdraw(tryWithdraw) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        uint256 cBalAfterWithdraw = address(c).balance;

        // attempt refund and record if it reverted
        bool refundedReverted;
        try c.refund() {
            refundedReverted = false;
        } catch {
            refundedReverted = true;
        }

        uint256 cBalAfterRefund = address(c).balance;

        // After refund (whether earlier withdraw happened or not), attempt to withdraw the total deposited amount dep1+dep2
        bool withdrawAfterRefundReverted;
        uint256 totalDeposited = dep1 + dep2;
        try c.withdraw(totalDeposited) {
            withdrawAfterRefundReverted = false;
        } catch {
            withdrawAfterRefundReverted = true;
        }

        // If refund succeeded then the contract balance must have strictly decreased (some funds sent out),
        // and any immediate withdraw of the prior-deposited total must revert (since refund zeroes caller balance).
        assert(
            (refundedReverted) || (cBalAfterRefund < cBalBefore && withdrawAfterRefundReverted)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    address payable creator;

    constructor(C _c) {
        c = _c;
        // The test harness deploys C with this InvMutTest as msg.sender, so this contract is the creator.
        creator = payable(address(this));
    }

    // single public test function
    // We don't need to send ETH to c here; the rule concerns migrateTo forwarding the contract's balance.
    // However, to ensure there's some balance to forward, accept an amount param and deposit it first.
    function run(uint256 depositAmount, address payable to) public payable {
