contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test entry. We will first deposit some funds on behalf of this contract, then call refund.
    function run(uint256 depositAmount) public payable {
        // ensure this test contract can send the requested amount to c
        require(address(this).balance >= depositAmount);

        // Observe contract balance before deposit
        uint256 beforeContractBal = address(c).balance;

        // Try deposit; capture whether it reverted
        bool depReverted;
        try c.deposit{value: depositAmount}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        // Observe contract balance after deposit attempt
        uint256 afterDepositContractBal = address(c).balance;

        // Now attempt refund and capture whether it reverted
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // Observe contract balance after refund attempt
        uint256 afterRefundContractBal = address(c).balance;

        // We can observe the per-address stored balance only via effects: after a successful refund,
        // address(c).balance must have decreased by exactly the amount that was transferred to msg.sender.
        // Also, refund sets the stored balance for the caller to zero; since there is no getter for balances,
        // we infer that a successful refund cannot leave address(c).balance decreased by more than beforeDeposit -> afterRefund

        // General rule asserted:
        // If refund did not revert then:
        //  - the contract balance after refund is <= contract balance after deposit, and
        //  - the decrease in contract balance from afterDepositContractBal to afterRefundContractBal equals the decrease from beforeContractBal to afterRefundContractBal minus the increase caused by a non-reverted deposit (i.e., consistency of observed balances),
        //  - equivalently: if deposit succeeded then (afterDepositContractBal == beforeContractBal + depositAmount); if deposit reverted then afterDepositContractBal == beforeContractBal.
        // Finally, if refund succeeded then afterRefundContractBal <= afterDepositContractBal and the net decrease (afterDepositContractBal - afterRefundContractBal) is exactly the amount that must have been held for this caller (nonzero only if deposit earlier succeeded).

        // To avoid relying on internal mapping getters, we assert two observable consistency facts:
        // 1) deposit success implies the contract balance increased by depositAmount; deposit revert implies no change.
        // 2) if refund succeeded then contract balance did not increase compared to afterDepositContractBal, and the amount decreased by refund is <= afterDepositContractBal - beforeContractBal (can't refund more than available increase for this caller).

        assert(
            // 1) deposit observable consistency
            (depReverted ? (afterDepositContractBal == beforeContractBal) : (afterDepositContractBal == beforeContractBal + depositAmount))
            // AND 2) refund observable constraints
            && (refundReverted ? true : (
                // refund succeeded: contract balance cannot have increased compared to afterDeposit
                (afterRefundContractBal <= afterDepositContractBal)
                // and refunded amount cannot exceed total increase that could be attributed to this caller
                && ((afterDepositContractBal - afterRefundContractBal) <= (afterDepositContractBal - beforeContractBal))
            ))
        );
    }

    receive() external payable {}
}

