        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // record contract balance after refund attempt and this contract balance
        uint256 afterContractBalance = address(c).balance;
        uint256 afterThisBalance = address(this).balance;

        // General rule:
        // - If refund reverted, then address(c).balance is unchanged from after the deposit attempt.
        // - If refund succeeded, then address(c).balance decreased by exactly the increase that succeeded from the prior deposit attempt (i.e., afterDepositContractBalance - beforeContractBalance), and this contract's balance increased by that same amount.
        assert(
            (refundReverted && afterContractBalance == afterDepositContractBalance)
            || (!refundReverted
                && afterDepositContractBalance >= beforeContractBalance // sanity: deposit couldn't make contract have less than before
                && afterContractBalance + (afterDepositContractBalance - beforeContractBalance) == beforeContractBalance
                && afterThisBalance == afterDepositThisBalance + (afterDepositContractBalance - beforeContractBalance)
            )
        );
    }

    // accept Ether to allow depositing into c
    receive() external payable {}
}

