contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: attempt withdraw and assert the invariant
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // Ensure this test contract has funds to deposit
        require(address(this).balance >= depositAmount);

        // Record observables before any calls
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeRecorded = c.balances(address(this));

        // Try to deposit depositAmount into c so caller has funds to withdraw later
        bool depReverted;
        try c.deposit{value: depositAmount}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        // Observables after deposit attempt
        uint256 afterDepositContractBal = address(c).balance;
        uint256 afterDepositRecorded = c.balances(address(this));

        // Now attempt withdraw(withdrawAmount)
        bool wdReverted;
        try c.withdraw(withdrawAmount) {
            wdReverted = false;
        } catch {
            wdReverted = true;
        }

        // Observables after withdraw attempt
        uint256 afterWithdrawContractBal = address(c).balance;
        uint256 afterWithdrawRecorded = c.balances(address(this));

        // General rule:
        // - If withdraw reverted then contract balance and recorded balance unchanged from after-deposit values.
        // - If withdraw succeeded then contract balance decreased by exactly withdrawAmount,
        //   and the recorded balance decreased by at least withdrawAmount (i.e., not larger than before by more than deposit effect).
        assert(
            wdReverted
            ? (afterWithdrawContractBal == afterDepositContractBal && afterWithdrawRecorded == afterDepositRecorded)
            : (
                // contract balance must fall by exactly withdrawAmount
                afterWithdrawContractBal + withdrawAmount == afterDepositContractBal
                // recorded balance must not have decreased by less than withdrawAmount (i.e., decrease >= withdrawAmount)
                && (afterDepositRecorded >= afterWithdrawRecorded) // monotone nonincreasing
                && (afterDepositRecorded - afterWithdrawRecorded >= withdrawAmount)
            )
        );
    }

    // Accept Ether sent back from contract when withdraw/refund/migrate happen
    receive() external payable {}
}

