contract InvMutTest {
    C c;
    address payable creator;
    constructor(C _c) { c = _c; }

    // Try to call migrateTo as either the creator or a non-creator and assert observable rules about address(c).balance and revert behavior.
    function run(address to, bool callAsCreator) public payable {
        // We must ensure this contract has some funds to avoid zero-balance corner but do not call deposit on c (deposit may assert); instead fund c via migrateTo from creator later.
        // Read contract balance before any interaction
        uint256 beforeBal = address(c).balance;

        // We will attempt migrateTo from this contract. The real contract's creator is the deployer of C (the checker deploys C fresh and passes it to this test's constructor),
        // but we cannot become that creator. So this test distinguishes two cases: when callAsCreator==false we expect migrateTo to revert and balance unchanged;
        // when callAsCreator==true we attempt the call and allow either revert or success, but require success cannot increase address(c).balance.

        bool migratedReverted;
        if (!callAsCreator) {
            // As a non-creator caller, migrateTo must revert and leave balance unchanged.
            try c.migrateTo(to) {
                migratedReverted = false;
            } catch {
                migratedReverted = true;
            }
            uint256 afterBal = address(c).balance;
            // If not creator, it must revert (i.e., migratedReverted==true) and balance unchanged.
            assert(migratedReverted && afterBal == beforeBal);
        } else {
            // callAsCreator == true: we cannot actually become the original creator, so the realistic possibility is that this call will revert.
            // However, to make a meaningful general rule we assert: after the attempt, contract balance never increases; if it succeeded then it moved out at most the previous balance.
            try c.migrateTo(to) {
                migratedReverted = false;
            } catch {
                migratedReverted = true;
            }
            uint256 afterBal = address(c).balance;
            // General rule: migrateTo never increases contract balance; if it succeeded then afterBal <= beforeBal, if it reverted then afterBal == beforeBal.
            assert(migratedReverted ? (afterBal == beforeBal) : (afterBal <= beforeBal));
        }
    }

    // allow receiving ether if migrateTo succeeds
    receive() external payable {}
}

