contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit some Ether into c from this contract, then call refund()
    // and assert that either refund reverted and contract balance unchanged, or refund succeeded and the caller's recorded balance is cleared (so subsequent withdraw of any positive amount reverts).
    function run(uint256 depositAmount, uint256 tryWithdraw) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");
        // record contract balance before deposit
        uint256 before = address(c).balance;

        // perform deposit (may revert)
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        uint256 afterDeposit = address(c).balance;

        // If deposit succeeded then afterDeposit == before + depositAmount; if reverted then unchanged.
        // Now call refund()
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        uint256 afterRefund = address(c).balance;

        // Attempt a withdraw of tryWithdraw to test whether recorded balance for this caller was cleared by refund.
        // We only attempt when tryWithdraw > 0. Capture whether it reverts.
        bool withdrawReverted;
        if (tryWithdraw > 0) {
            try c.withdraw(tryWithdraw) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        } else {
            // if tryWithdraw == 0, avoid calling withdraw; treat as not reverted (no meaningful test)
            withdrawReverted = false;
        }

        // General rule asserted:
        // - If refund reverted then contract balance unchanged from afterDeposit.
        // - If refund succeeded then withdraw of any positive amount must revert (because refund should zero caller's balance), and contract balance decreased by exactly the amount returned to caller (i.e., afterRefund <= afterDeposit).
        assert(
            (refundReverted && afterRefund == afterDeposit)
            || (!refundReverted && tryWithdraw > 0 && withdrawReverted && afterRefund <= afterDeposit)
        );
    }

    receive() external payable { }
}
